// План specs/stripe-connect.md 1.4 (#458056, связан #06a307 / #5e4fe6). Pre-Prod (Stripe test mode), preprod-ttp → переключатель компаний → «QA-Connect 1211»,
// десктоп, EN. Только чтение (@prod-safe): возврат уже выполнен 12.11 (JOB-0001, Payment Link $1.00); новых платежей/возвратов нет.
// Источник: тикет — после Refund платежа из Payment Link блок «Payment links» в работе показывает «Refunded», а не «$1.00 Paid».
// Факты 17.11: QA-Connect 1211 → JOB-0001 → Payment links: $1.00 Refunded; в Payment history — Credit Card $1.00 Refunded.
// В finally выбирается обратно «TTP Test Locks». Не сверено с сайтом при записи: роль строки блока Payment links, переключатель компаний (кнопка с названием).
import { test, expect } from '../../fixtures';
import { COMPANY, pp } from '../job-payments/payments-helpers';
import { ROLE } from '../pricebook/pricebook-helpers';

const CONNECT_COMPANY = 'QA-Connect 1211';

test.describe('Job → Payment links after a refund (#458056)', () => {
  test('QA-Connect 1211 → JOB-0001 → Payments: the $1.00 payment link is "Refunded", not "Paid"; payment history also Refunded #458056 @desktop @prod-safe', async ({ asUser }) => {
    test.setTimeout(120_000);
    const page = await asUser(ROLE);
    await page.addInitScript(() => { try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ } });
    const switcher = () => page.getByRole('button').filter({ hasText: new RegExp(`^\\s*(${COMPANY}|${CONNECT_COMPANY})\\s*$`) }).first();
    try {
      await page.goto(pp('/dashboard'));
      await expect(switcher()).toBeVisible({ timeout: 30_000 });
      await switcher().click();
      await page.getByText(CONNECT_COMPANY, { exact: true }).filter({ visible: true }).first().click();
      await expect(switcher()).toContainText(CONNECT_COMPANY);

      await page.goto(pp('/jobs'));
      await page.getByText('JOB-0001', { exact: true }).filter({ visible: true }).first().click();
      await page.waitForURL(/\/JobDetail\?id=/, { timeout: 30_000 });
      await page.getByRole('tab', { name: /^Payments/ }).click();
      await expect(page.getByRole('heading', { name: 'Job Payments' })).toBeVisible();

      const links = page.locator('div').filter({ has: page.getByText('Payment links', { exact: true }) }).last();
      const linkRow = links.locator('div').filter({ hasText: '$1.00' }).filter({ hasText: 'Refunded' }).first();
      await expect(linkRow, 'ссылка $1.00 помечена Refunded').toBeVisible();
      await expect(links.getByText('Paid', { exact: true }), 'в блоке Payment links нет «Paid»').toHaveCount(0);

      const history = page.getByRole('main').getByRole('row').filter({ hasText: 'Credit Card' });
      await expect(history.first()).toContainText('Refunded');
    } finally {
      if (!page.isClosed()) {
        await page.goto(pp('/dashboard')).catch(() => {});
        if (await switcher().isVisible().catch(() => false)) {
          const text = (await switcher().innerText().catch(() => '')).trim();
          if (text.includes(CONNECT_COMPANY)) {
            await switcher().click();
            await page.getByText(COMPANY, { exact: true }).filter({ visible: true }).first().click().catch(() => {});
          }
        }
      }
    }
  });
});
